def solve(status, method, idempotent):
    if status == 429:
        return "backoff"
    if 200 <= status < 300:
        return "ok"
    if 400 <= status < 500:
        return "caller"
    if status >= 500 and (method == "GET" or idempotent):
        return "retry"
    if status >= 500:
        return "unavailable"
    return "unknown"
